<script setup lang="ts">
import {computed,ref,reactive} from 'vue'
import RecordPage from '../../components/RecordPage.vue'
import type {Definition,Row} from '../../shared/records'
import {http} from '../../api/http'
import {navigation} from '../../navigation'
const roleOptions=[{value:'ADMIN',label:'系统管理员'},{value:'CANTEEN',label:'食堂工作人员'},{value:'FAMILY',label:'老年人家属'},{value:'COMMUNITY',label:'社区操作员'}]
const permissionOptions=[{"value": "users:write", "label": "操作：管理用户和权限"}, {"value": "sites:write", "label": "操作：维护服务网点"}, {"value": "dishes:write", "label": "操作：维护菜品与价格"}, {"value": "elders:write", "label": "操作：维护老人档案"}, {"value": "health:write", "label": "操作：维护健康资料"}, {"value": "subsidies:review", "label": "操作：审核补贴资格"}, {"value": "bindings:review", "label": "操作：审核家属绑定"}, {"value": "menus:write", "label": "操作：上报维护菜谱"}, {"value": "menus:publish", "label": "操作：发布每日菜谱"}, {"value": "orders:create", "label": "操作：创建订单"}, {"value": "orders:cancel", "label": "操作：取消订单"}, {"value": "orders:prepare", "label": "操作：备餐出餐"}, {"value": "redemptions:write", "label": "操作：取餐核销"}, {"value": "delivery:write", "label": "操作：配送状态更新"}, {"value": "refunds:review", "label": "操作：审核退款"}, {"value": "preparation:write", "label": "操作：调整备餐量"}, {"value": "recommendation:write", "label": "操作：配置膳食推荐"}, {"value": "reviews:write", "label": "操作：提交菜品评价"}, {"value": "tickets:write", "label": "操作：回复处理工单"}, {"value": "notices:write", "label": "操作：发布维护公告"}].concat(Object.values(navigation).flat().map(item=>({value:'menu:'+item.path,label:'菜单：'+item.label+'（'+item.path.split('/')[1]+'）'})))

const definition:Definition={title:'用户与权限',endpoint:'/users',columns:[['username','账号'],['realName','姓名'],['status','状态']],fields:[{key:'username',label:'登录账号'},{key:'password',label:'初始密码（编辑时留空）',type:'password'},{key:'realName',label:'姓名'},{key:'phone',label:'新联系电话（留空保留）'},{key:'roles',label:'角色',type:'multi',options:roleOptions,initial:['FAMILY']},{key:'siteIds',label:'授权网点',type:'multi',source:'/sites?size=100'},{key:'denied',label:'禁用的菜单或操作',type:'multi',options:permissionOptions}],save:async(body,id)=>{const denied=body.denied??[];delete body.denied;const roles=body.roles,siteIds=body.siteIds??[];if(id){delete body.username;delete body.password;delete body.roles;delete body.siteIds}const result=id?await http.put<never,Row>(`/users/${id}`,body):await http.post<never,Row>('/users',body);if(id){await http.put(`/users/${id}/roles`,{roles});await http.put(`/users/${id}/sites`,{siteIds})}await http.put(`/users/${result.id}/permissions`,{denied})}}
const selected=ref<Row|null>(null),password=ref(''),error=ref(''),saving=ref(false)
async function reset(){if(!selected.value||saving.value)return;saving.value=true;error.value='';try{await http.post(`/users/${selected.value.id}/reset-password`,{password:password.value});selected.value=null}catch(e){error.value=(e as Error).message}finally{saving.value=false}}

</script>
<template><div><RecordPage :definition="definition"><template #actions="{row,action}"><el-button link @click="action('PATCH',`/users/${row.id}/status`,{status:row.status==='ACTIVE'?'DISABLED':'ACTIVE'})">{{row.status==='ACTIVE'?'停用':'启用'}}</el-button><el-button link @click="selected=row;password='';error=''">重置密码</el-button></template></RecordPage><el-dialog :model-value="!!selected" title="重置密码" width="min(600px,94vw)" @close="selected=null"><el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="form-stack" @submit.prevent="reset"><label for="reset-password">新密码</label><el-input id="reset-password" v-model="password" type="password" show-password/><el-button native-type="submit" type="primary" :loading="saving">保存</el-button></form></el-dialog></div></template>
